<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {federationJobsApi as api,type Job} from '../../infrastructure/federationJobsApi'
const items=ref<Job[]>([]),page=ref(1),total=ref(0),kind=ref('delivery'),state=ref(''),busy=ref(false),error=ref(''),notice=ref('')
const labels:Record<string,string>={pending:'待处理／等待重试',processing:'处理中',failed:'失败',delivered:'已投递',processed:'已展开',cancelled:'已取消'}
async function load(reset=false){if(reset)page.value=1;busy.value=true;error.value='';try{const d=await api.jobs(page.value,kind.value,state.value);items.value=d.items;total.value=d.total}catch{error.value='无法读取任务队列。'}finally{busy.value=false}}
async function act(job:Job,action:'retry'|'cancel'){if(busy.value)return;if(!window.confirm(action==='cancel'?'确认取消此待处理任务？该事件将不会继续投递，可能导致远端状态不同步。':'确认立即重试此任务？将保留原活动 ID，正在执行的任务不会被重复启动。'))return;busy.value=true;error.value='';try{await api.jobAction(job,action);notice.value=action==='retry'?'已安排重试。':'任务已取消。';await load()}catch{error.value='任务已变化、正在执行或操作失败，请刷新确认。'}finally{busy.value=false}}
onMounted(()=>load())
</script>
<template><div class="admin-page"><header><h1>联邦作业与任务队列</h1><p>事件队列负责展开收件人，投递队列负责网络发送。手动重试保留原活动标识；取消不能撤回已经发送的内容。</p></header><form class="admin-card admin-toolbar" @submit.prevent="load(true)"><label class="admin-field">队列<select v-model="kind"><option value="delivery">ActivityPub 投递</option><option value="outbox">已提交事件</option></select></label><label class="admin-field">状态<select v-model="state"><option value="">全部</option><option v-for="(label,key) in labels" :key="key" :value="key">{{ label }}</option></select></label><button class="admin-button" :disabled="busy">查询／刷新</button></form><p v-if="error" role="alert" class="admin-error">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p><section class="admin-card" :aria-busy="busy"><p v-if="busy">加载中…</p><p v-else-if="!items.length" class="admin-empty">没有匹配的任务。</p><article v-for="job in items" :key="job.id" class="admin-card"><strong>#{{ job.id }} · {{ labels[job.state]||job.state }}</strong><p>{{ job.event||job.activity_id }}</p><p v-if="job.destination">目标：{{ job.destination }}</p><p>尝试次数：{{ job.attempts }} <span v-if="job.next_attempt_at">计划时间：{{ new Date(job.next_attempt_at).toLocaleString() }}</span></p><p v-if="job.last_error" class="admin-error">{{ job.last_error }}</p><div v-if="['failed','pending'].includes(job.state)" class="admin-toolbar"><button class="admin-button" :disabled="busy" @click="act(job,'retry')">立即重试</button><button class="admin-button admin-button--danger" :disabled="busy" @click="act(job,'cancel')">取消任务</button></div></article></section><div class="admin-toolbar"><button class="admin-button" :disabled="busy||page===1" @click="page--;load()">上一页</button><span>第{{ page }}页，共{{ total }}项</span><button class="admin-button" :disabled="busy||page*30>=total" @click="page++;load()">下一页</button></div></div></template>
